                border_left =rep("",5)
  ) |&gt; 
  rtf_colheader(" | n  (%) | n  (%) | n  (%) | n  (%) ",
                col_rel_width =c(3, rep(2, 4)),
                border_top = rep("",5),
                border_right = rep("",5),
                border_left =rep("",5)
  ) |&gt; 
  rtf_body(
    #page_by = "var_label",
    col_rel_width = c(3, rep(2, 4)),
    text_justification = c("l", rep("c", 4)),
    #text_format = c(rep("", 5), "b"),
    border_top = rep("",5),
    border_right = rep("",5),
    border_left =rep("",5)
  ) |&gt; 
  rtf_footnote("This is a footnote",
               border_left = "",
               border_right = "",
               border_bottom = "") 


# Output .rtf file
